#include <iostream>

int main() {
    // Input validation: process grades in sequence
    int grade1{0};
    int grade2{0};

    if (std::cin >> grade1 >> grade2) {
        // Sequence structure: compute total, then increment counter
        int total{0};
        int counter{0};

        total = total + grade1;
        counter = counter + 1;

        total = total + grade2;
        counter = counter + 1;

        // Stacked sequence: calculate and print average
        int average = total / counter;
        std::cout << "Total: " << total << "\n";
        std::cout << "Count: " << counter << "\n";
        std::cout << "Average: " << average << "\n";
    }

    return 0;
}

#include <iostream>

int main() {
    int grade{0};

    if (std::cin >> grade) {
        // Industrial-strength code: validate input range [0, 100]
        if (grade < 0) {
            std::cout << "Invalid: negative grade\n";
            return 0;
        }
        if (grade > 100) {
            std::cout << "Invalid: grade exceeds 100\n";
            return 0;
        }

        // Single-selection statement based on condition
        if (grade >= 60) {
            std::cout << "Passed\n";
        }

        // Demonstrating non-zero integer evaluation compatible with C
        int legacyStatus = (grade >= 60); // 1 if true, 0 if false
        if (legacyStatus) {
            std::cout << "Legacy check: Non-zero evaluates to true\n";
        }
    }

    return 0;
}
